import numpy as np

EXCLUDE = {"event_id", "i", "j", "k", "is_truth", "n_truth_in_event", "triplet_phi"}
BTAG_COLS = {"btag1", "btag2", "btag3", "n_btag", "btag_of_lowest_pt", "n_btag_event"}
RANK_COLS = {"dm_W_best_rank", "dr_max_rank", "pt_sum_rank", "triplet_mass_rank", "dm_top_rank"}
CTX_COLS = {"ht", "event_mass", "pt_frac_of_ht", "n_genjet", "n_triplet_cand",
            "idx_sum", "idx_max", "idx_spread", "n_btag_event"}


def feature_list(df, use_btag=True, use_rank=True, use_ctx=True):
    cols = [c for c in df.columns if c not in EXCLUDE]
    if not use_btag:
        cols = [c for c in cols if c not in BTAG_COLS]
    if not use_rank:
        cols = [c for c in cols if c not in RANK_COLS]
    if not use_ctx:
        cols = [c for c in cols if c not in CTX_COLS]
    return cols


def roc_auc(y, s):
    y = np.asarray(y).astype(np.int8)
    s = np.asarray(s, dtype=np.float64)
    n1 = int(y.sum()); n0 = len(y) - n1
    if n1 == 0 or n0 == 0:
        return float("nan")
    order = np.argsort(s, kind="mergesort")
    sv = s[order]
    ranks = np.empty(len(s), dtype=np.float64)
    i = 0
    while i < len(sv):
        j = i
        while j + 1 < len(sv) and sv[j + 1] == sv[i]:
            j += 1
        ranks[order[i:j + 1]] = 0.5 * (i + j) + 1.0
        i = j + 1
    return float((ranks[y == 1].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))


def average_precision(y, s):
    y = np.asarray(y).astype(np.int8)
    order = np.argsort(-np.asarray(s), kind="mergesort")
    yy = y[order]
    tp = np.cumsum(yy)
    prec = tp / np.arange(1, len(yy) + 1)
    n1 = int(y.sum())
    return float((prec * yy).sum() / n1) if n1 else float("nan")


def roc_curve(y, s, n_pts=200):
    y = np.asarray(y).astype(np.int8)
    order = np.argsort(-np.asarray(s), kind="mergesort")
    yy = y[order]
    tp = np.cumsum(yy); fp = np.cumsum(1 - yy)
    tpr = tp / max(tp[-1], 1); fpr = fp / max(fp[-1], 1)
    idx = np.unique(np.linspace(0, len(yy) - 1, n_pts).astype(int))
    return fpr[idx], tpr[idx]

