import pandas as pd, numpy as np
K=['event_id','i','j','k']
def load(n): 
    d=pd.read_parquet(f'/root/work/scratch/{n}.parquet')[K+['is_truth','score']]
    return d.set_index(K).sort_index()
def sel_eff(d, alpha=0.5, w=1.0, topn=40):
    d=d.sort_values(['event_id','score'],ascending=[True,False])
    ev=d.event_id.values; S=d.score.values; I,J,K2=d.i.values,d.j.values,d.k.values; Y=d.is_truth.values.astype(int)
    b=np.flatnonzero(np.r_[True, ev[1:]!=ev[:-1], True]); got=0
    for b0,b1 in zip(b[:-1],b[1:]):
        m=b1-b0; s=np.maximum(S[b0:b1],1e-12)**alpha; y=Y[b0:b1]
        sets=[frozenset((I[b0+q],J[b0+q],K2[b0+q])) for q in range(m)]
        n=min(m,topn); best=-1e18; bp=(0,None)
        for a in range(n):
            if s[a]>best: best,bp=s[a],(a,None)
            for c in range(a+1,n):
                if sets[a]&sets[c]: continue
                v=s[a]+w*s[c]
                if v>best: best,bp=v,(a,c)
        got+=int(y[bp[0]])+(int(y[bp[1]]) if bp[1] is not None else 0)
    return got/Y.sum()
names=['cv_E_d3_seeds5_k5','cv_v3_d3_lr03','cv_v3_d4_lr03','cv_v3_d5_mcw10','cv2_H_top8_s2only_s2']
